import "server-only";
import type { Tx } from "@/db/tenant";
import { organizationMemberships, organizations, plans, roles } from "@/db/schema";
import { and, eq } from "drizzle-orm";
import { recordAudit } from "@/server/audit/record";
import { OWNER_ROLE_KEY, SYSTEM_ROLES } from "@/server/authz/system-roles";
import { invalid } from "@/server/errors";

export const DEFAULT_PLAN_KEY = "essencial";

/**
 * Creates the tenant, its system roles and the owner membership. Must run
 * inside withScope({ organizationId, userId }) with ids generated by the caller,
 * because RLS only accepts rows of the organization set for the transaction.
 * `actorUserId` is who registers it (the platform administrator); defaults to the owner (self sign-up).
 */
export async function provisionOrganization(
  tx: Tx,
  input: { organizationId: string; ownerUserId: string; name: string; document?: string; planKey?: string; actorUserId?: string },
) {
  const actorUserId = input.actorUserId ?? input.ownerUserId;
  const [plan] = await tx
    .select({ key: plans.key })
    .from(plans)
    .where(and(eq(plans.key, input.planKey ?? DEFAULT_PLAN_KEY), eq(plans.isActive, true)));
  if (!plan) {
    throw input.planKey
      ? invalid("Plano inválido.", { planKey: ["Selecione um plano ativo."] })
      : invalid("Catálogo de planos não configurado. Execute as migrations do banco.");
  }

  await tx.insert(organizations).values({
    id: input.organizationId,
    name: input.name,
    document: input.document ?? null,
    planKey: plan.key,
  });

  const created = await tx
    .insert(roles)
    .values(
      SYSTEM_ROLES.map((role) => ({
        organizationId: input.organizationId,
        key: role.key,
        name: role.name,
        description: role.description,
        isSystem: true,
        rank: role.rank,
      })),
    )
    .returning({ id: roles.id, key: roles.key });
  const ownerRole = created.find((role) => role.key === OWNER_ROLE_KEY);
  if (!ownerRole) throw new Error("Owner role was not created");

  const [membership] = await tx
    .insert(organizationMemberships)
    .values({
      organizationId: input.organizationId,
      userId: input.ownerUserId,
      roleId: ownerRole.id,
      storeAccess: "all",
      createdBy: actorUserId,
    })
    .returning({ id: organizationMemberships.id });

  await recordAudit(tx, {
    organizationId: input.organizationId,
    actorUserId,
    action: "organization.created",
    entityType: "organization",
    entityId: input.organizationId,
    changes: { name: input.name, plan: plan.key },
  });
  return { membershipId: membership.id, planKey: plan.key };
}
